SELECT room_id, room_number, branch_id, category_id, floor_level, has_balcony, status
FROM accommodations
WHERE status = 'Occupied';

SELECT gp.title, sm.full_name
FROM game_project gp
JOIN studio_member sm ON gp.lead_producer_id = sm.member_id;

SELECT medication_id, generic_name, brand_name, strength, dosage_form, manufacturer, category_id, unit_cost, reorder_level, is_active, created_date
FROM medications
WHERE is_active = 1 AND unit_cost > 0.50;

SELECT f.tail_number, a.airline_name, a.hub_airport_code
FROM fleet f
JOIN airlines a ON f.airline_id = a.airline_id;

SELECT generic_name, brand_name, strength, controlled_substance_schedule
FROM medication_catalog
WHERE controlled_substance_schedule >= 2;

SELECT inventory_stock.item_name, supply_categories.category_name, supply_categories.storage_type
FROM inventory_stock
JOIN supply_categories ON inventory_stock.category_id = supply_categories.category_id;

SELECT outlet_id, COUNT(*) AS team_member_count
FROM team_members
GROUP BY outlet_id;

SELECT ca.full_name, st.tier_name, st.monthly_fee
FROM customer_accounts ca
JOIN subscription_tiers st ON ca.tier_id = st.tier_id;

SELECT session_type, SUM(volume_mb) AS total_volume_mb
FROM usage_events
GROUP BY session_type;

SELECT age_group, AVG(registration_fee) AS average_registration_fee
FROM divisions
GROUP BY age_group;
